async function foundationPanel(){
 const root=$('#foundation-panel');if(!root)return;
 const [f,s]=await Promise.all([api('foundation'),api('knowledge-storage')]);
 root.replaceChildren(el('h2','','Offline foundation & federated storage'));
 const d=f.dictionary;root.append(el('p','',d?`${d.counts.lemmas.toLocaleString()} English lemmas · ${d.counts.senses.toLocaleString()} WordNet senses · ${(d.compressedBytes/1048576).toFixed(1)} MiB compressed. Loaded on demand; ${d.cachedShards} dictionary shards cached.`:'Dictionary disabled'),el('p','notice','Dictionary entries attest meanings; they do not guarantee correct context, up-to-date facts, or universal understanding.'));
 const lookup=el('form','inline'),label=el('label','','Find an offline word'),input=el('input');input.name='word';input.required=true;input.maxLength=200;input.placeholder='microscope, bank, children';label.append(input);const submit=el('button','primary','Look up');lookup.append(label,submit);const results=el('div','cards');lookup.addEventListener('submit',run(async e=>{e.preventDefault();const r=await api('foundation/lookup?word='+encodeURIComponent(input.value));results.replaceChildren();if(!r.senses?.length){results.append(el('p','','No bundled sense found. This remains a knowledge gap.'));return;}results.append(el('p','',`${r.total} ${r.total===1?'sense':'senses'} available${r.truncated?' · showing the first 20':''}. Morphology: ${r.forms.join(', ')||'lemma'}`));for(const x of r.senses){const c=el('article','card');c.append(el('h3','',x.words.map(w=>w.replaceAll('_',' ')).join(', ')),el('p','',x.definition),el('small','',`${x.id} · ${x.pos} · ${x.license}`));for(const example of x.examples.slice(0,2))c.append(el('p','','Example: '+example));c.append(button('Store reviewed dictionary atom',async()=>{const out=await api('knowledge-storage/commit',{id:x.id});toast(`${out.state} · ${(out.locations||[]).length} verified locations`);await foundationPanel();}));results.append(c);}}));root.append(lookup,results);
 root.append(el('h3','','Storage policy'),el('p','',`${s.records} committed manifests · ${s.pending} pending writes · ${s.policy.requiredIndependentDurableDomains} independent durable domain(s) required.`));
 for(const p of s.providers){const c=el('article','card');c.append(el('h3','',p.id+' · '+p.type),el('p','',`${p.durable?'Configured durable backend':'Cache / ephemeral backend; does not count toward durability'} · domain: ${p.domain}`),el('small','',`${p.capacity.measurement} · ${p.capacity.usedBytes===null?'provider usage unknown':p.capacity.usedBytes+' bytes stored'} · budget ${p.capacity.maxBytes??'?'} bytes · ${p.metrics.requests} budgeted operations · ${p.metrics.failures} failures`));root.append(c);}
 root.append(el('p','notice','Cloud accounts are not created here. Keys stay server-side. A committed local record is not proof of cloud or global replication. Hosted ephemeral files do not count as durable copies.'),button('Retry pending storage writes',async()=>{const r=await api('knowledge-storage/recover',{});toast(`${r.results.length} pending writes checked`);await foundationPanel();}));
}
